// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ModifierEntrancy} from "../src/ModifierEntrancy.sol";

contract InvMutTest is Test {
    ModifierEntrancy c;
    function setUp() public { c = new ModifierEntrancy(); }

    function testFuzz_property(address actor) public {
        vm.assume(actor != address(0));

        TokenHolder helper = new TokenHolder();

        vm.prank(address(helper));
        bool ok;
        try c.airDrop() {
            ok = true;
        } catch {
            ok = false;
        }

        uint bal = c.tokenBalance(address(helper));
        assertTrue((ok && bal == 20) || (!ok && bal == 0));
    }
}

contract TokenHolder {
    function supportsToken() external pure returns (bytes32) {
        return keccak256(abi.encodePacked("Nu Token"));
    }
}
